def _operator(u, v, kind):
    from scipy.optimize import least_squares
    from scipy.linalg import lstsq

    def basis(x, q):
        z = x * q
        f = np.arcsinh(z) if kind == 1 else np.logaddexp(z, -z) - np.log(2.0)
        return np.column_stack((_aff(x), f))

    def residual(q):
        a = basis(u, q)
        return (a @ lstsq(a, v)[0] - v).ravel()
    q = least_squares(residual, np.full(4, 3.5 if kind == 1 else 1.1), bounds=(0.2, 8.0), max_nfev=100).x
    c = lstsq(basis(u, q), v)[0]
    return lambda x: basis(x, q) @ c

def _basis(t, traj):
    from scipy.optimize import least_squares
    from scipy.linalg import lstsq

    def base(q):
        return -np.expm1(-t[:, None] * np.sort(q))

    def residual(q):
        f = base(q)
        return (f @ lstsq(f, traj.T)[0] - traj.T).ravel()
    fit = least_squares(residual, [0.4, 1.8], bounds=(0.03, 15.0))
    return base(fit.x)

def _kernels(z):
    from scipy.spatial.distance import cdist
    d = cdist(z, z, 'sqeuclidean') / z.shape[1]
    r = np.sqrt(d)
    for h in (0.55, 1.0, 1.7):
        q = h * r
        yield ('m' + str(h), (1 + q + q * q / 3) * np.exp(-q))
    for h in (0.2, 0.5, 1.0):
        yield ('r' + str(h), np.exp(-h * d))
    if z.shape[1] == 4:
        dz = (z[:, None, :] - z[None, :, :]) ** 2
        for h in (0.3, 0.7):
            u = np.exp(-h * dz)
            v = u.mean(axis=2)
            w = (u.sum(axis=2) ** 2 - (u * u).sum(axis=2)) / 12
            yield ('anova' + str(h), 0.2 * v + 0.4 * w + 0.4 * np.exp(-h * d))

def fit(u, v, fn, k0, shift, linear):
    from scipy.optimize import least_squares
    from scipy.linalg import lstsq

    def basis(x, q):
        z = x * q[:4] + (q[4:] if shift else 0)
        a = fn(z)
        return np.column_stack((np.ones(len(x)), x, a)) if linear else np.column_stack((np.ones(len(x)), a))

    def residual(q):
        A = basis(u, q)
        return (A @ lstsq(A, v)[0] - v).ravel()
    x0 = np.r_[np.full(4, k0), np.zeros(4) if shift else []]
    q = least_squares(residual, x0, bounds=(np.r_[np.full(4, 0.1), np.full(4, -2) if shift else []], np.r_[np.full(4, 5.0), np.full(4, 2) if shift else []]), max_nfev=150).x
    A = basis(u, q)
    c = lstsq(A, v)[0]
    return (lambda x: basis(x, q) @ c, q, c)
